/// A single suggestion candidate generated by an autocomplete or spell-check engine.
class Suggestion implements Comparable<Suggestion> {
  final String text;
  final double score;
  final Map<String, dynamic>? payload;
  final int distance;
  final int frequency;

  const Suggestion({
    required this.text,
    required this.score,
    this.payload,
    this.distance = 0,
    this.frequency = 0,
  });

  @override
  int compareTo(Suggestion other) {
    // Higher score first
    final cmp = other.score.compareTo(score);
    if (cmp != 0) return cmp;
    // Tie-break by lower edit distance
    final distCmp = distance.compareTo(other.distance);
    if (distCmp != 0) return distCmp;
    // Tie-break by higher frequency
    final freqCmp = other.frequency.compareTo(frequency);
    if (freqCmp != 0) return freqCmp;
    // Lexicographic tie-break
    return text.compareTo(other.text);
  }

  Map<String, dynamic> toJson() => {
        'text': text,
        'score': score,
        if (distance > 0) 'distance': distance,
        if (frequency > 0) 'frequency': frequency,
        if (payload != null) 'payload': payload,
      };

  @override
  String toString() => 'Suggestion($text, score: ${score.toStringAsFixed(3)}, dist: $distance)';
}

/// Execution parameters for completion suggesters.
class CompletionOptions {
  final int maxResults;
  final bool fuzzy;
  final int maxEdits;
  final int prefixLength;
  final bool transpositions;

  const CompletionOptions({
    this.maxResults = 5,
    this.fuzzy = false,
    this.maxEdits = 1,
    this.prefixLength = 1,
    this.transpositions = true,
  });
}
